package br.com.folha.notes;
import android.app.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.util.LruCache;import java.util.*;import java.util.concurrent.*;
/** Continuous reading only. The ink editor remains isolated from background rendering. */
final class ReadingPanel {
 final MainActivity a;final Documents.Doc doc;final ListView list;final BaseAdapter adapter;final ExecutorService worker=MainActivity.background("folha-reading");final Set<Integer> pending=new HashSet<>();final LruCache<Integer,Bitmap> cache=new LruCache<Integer,Bitmap>(16*1024*1024){protected int sizeOf(Integer key,Bitmap b){return b.getByteCount();}};volatile boolean closed;AlertDialog dialog;
 ReadingPanel(MainActivity a){this.a=a;a.readingPanel=this;doc=a.current.copy();list=new ListView(a);list.setDividerHeight(a.dp(18));list.setBackgroundColor(UiTheme.color(a.dark,0xFFE4E7E1));adapter=new BaseAdapter(){public int getCount(){return doc.count;}public Object getItem(int p){return p;}public long getItemId(int p){return p;}public View getView(int p,View old,android.view.ViewGroup parent){LinearLayout row=old instanceof LinearLayout?(LinearLayout)old:a.column();TextView label;ImageView image;if(row.getChildCount()==0){label=a.text("",13,MainActivity.INK,true);image=new ImageView(a);image.setAdjustViewBounds(false);image.setScaleType(ImageView.ScaleType.FIT_CENTER);row.addView(label);row.addView(image,new LinearLayout.LayoutParams(-1,a.dp(580)));}else{label=(TextView)row.getChildAt(0);image=(ImageView)row.getChildAt(1);}label.setText("Página "+(p+1)+" · toque para anotar");image.setImageBitmap(cache.get(p));row.setOnClickListener(v->{dialog.dismiss();a.changePage(p-a.page);});if(cache.get(p)==null)request(p);return row;}};list.setAdapter(adapter);LinearLayout box=a.column();box.addView(a.text("Leitura contínua · toque numa página para escrever",12,MainActivity.MUTED,false));box.addView(list,new LinearLayout.LayoutParams(-1,-1));dialog=a.dialog().setTitle(doc.name).setView(box).setNegativeButton("Voltar à escrita",null).create();dialog.setOnDismissListener(d->close());}
 void close(){if(closed)return;closed=true;if(dialog!=null&&dialog.isShowing())dialog.dismiss();worker.shutdownNow();list.setAdapter(null);cache.evictAll();if(a.readingPanel==this)a.readingPanel=null;}
 void show(){dialog.show();resize();list.setSelection(a.page);}
 void resize(){if(closed||dialog.getWindow()==null)return;dialog.getWindow().setLayout((int)(a.getResources().getDisplayMetrics().widthPixels*.94),(int)(a.getResources().getDisplayMetrics().heightPixels*.94));}
 void request(int p){if(closed||pending.size()>=3||!pending.add(p))return;worker.execute(()->{Bitmap b=null;try{if(closed)return;float w=Paper.width(doc.paper),h=Paper.height(doc.paper);if(doc.pdf){PdfFiles.Rendered r=PdfFiles.render(a.store.pdf(doc),p,1200);b=r.bitmap;w=r.width;h=r.height;}else{float s=Math.min(1200/w,1200/h);b=Bitmap.createBitmap(Math.round(w*s),Math.round(h*s),Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.scale(b.getWidth()/w,b.getHeight()/h);PageArt.paper(c,w,h,doc.paper);}List<Ink.Stroke> strokes=doc.pages.get(p);if(strokes!=null){Map<String,Bitmap> images=MediaFiles.page(a.store.dir(doc.id),strokes,1000);try{Canvas c=new Canvas(b);c.scale(b.getWidth()/w,b.getHeight()/h);PageArt.ink(c,strokes,images);}finally{MediaFiles.recycle(images);}}final Bitmap image=b;b=null;a.main.post(()->{pending.remove(p);if(closed){image.recycle();return;}cache.put(p,image);adapter.notifyDataSetChanged();});}catch(Exception|OutOfMemoryError e){if(b!=null)b.recycle();a.main.post(()->{pending.remove(p);if(!closed)a.toast("Não foi possível ler a página "+(p+1));});}});}
}
